// Pure research helpers. Never submit or send anything.
import {liquidityAt} from './research-early-pump-model.mjs';
export const S=300000,H=3600000;
export function volumeFeatures(raw,e,btc){const rows=raw.price.filter(b=>+b[6]<e.decisionAt).slice(-23);if(rows.length!==23||rows.some((b,i)=>+b[0]!==e.decisionAt-23*S+i*S||+b[6]+5000>e.availableAt))return{status:'MISSING_SIGNAL_CANDLES'};
const q=a=>a.reduce((s,b)=>s+ +b[7],0),old=q(rows.slice(0,20))/20,current=q(rows.slice(-3)),buy=rows.slice(-3).reduce((s,b)=>s+ +b[10],0);if(!(old>0&&current>0&&buy>=0&&buy<=current))return{status:'INVALID_VOLUME'};
const b=btc.price.filter(b=>+b[6]<e.decisionAt).slice(-13),btcOk=b.length===13&&b.every((r,i)=>+r[0]===e.decisionAt-13*S+i*S);
return{status:'OK',asOf:+rows.at(-1)[6],volume15m:current/(old*3),volume5m:+rows.at(-1)[7]/(q(rows.slice(-21,-1))/20),quote15m:current,sellPct:100*(1-buy/current),coin1h:100*(+rows.at(-1)[4]/+rows.at(-13)[4]-1),coin15m:100*(+rows.at(-1)[4]/+rows.at(-4)[4]-1),btc1h:btcOk?100*(+b.at(-1)[4]/+b.at(-13)[4]-1):null};}
export const FILTERS={ALL:()=>true,VOL_GE_1:f=>f.volume15m>=1,VOL_GE_1_5:f=>f.volume15m>=1.5,VOL_GE_2:f=>f.volume15m>=2,VOL_GE_3:f=>f.volume15m>=3,FLOW55:f=>f.sellPct>=55,VOL1_5_FLOW55:f=>f.volume15m>=1.5&&f.sellPct>=55};
export const BINS={'<1':f=>f.volume15m<1,'1–1.5':f=>f.volume15m>=1&&f.volume15m<1.5,'1.5–2':f=>f.volume15m>=1.5&&f.volume15m<2,'2–3':f=>f.volume15m>=2&&f.volume15m<3,'>=3':f=>f.volume15m>=3};
function pathAt(xs,start,n){const i=xs.findIndex(b=>+b[0]===start);if(i<0)return null;const out=xs.slice(i,i+n);return out.length===n&&out.every((b,j)=>+b[0]===start+j*S&&+b[6]===start+(j+1)*S-1)?out:null;}
export function excursion(raw,e){const path=pathAt(raw.price,e.entryAt,96);if(!path)return{status:'MISSING_PATH'};const entry=+path[0][1],low=Math.min(...path.map(b=>+b[3])),high=Math.max(...path.map(b=>+b[2]));return{status:'OK',maxDownPct:(1-low/entry)*100,maxUpPct:(high/entry-1)*100,down1:(1-low/entry)>=.01,down2:(1-low/entry)>=.02,down3:(1-low/entry)>=.03};}
export function modelSweep(raw,e,lag=S){const decisionBar=raw.mark.find(b=>+b[0]===e.decisionAt-S);if(!decisionBar)return{status:'MISSING_SIGNAL_MARK'};const reference=+decisionBar[4],liq=liquidityAt(raw,{at:e.decisionAt},reference,lag);if(liq.status!=='OK')return{status:liq.status};
const seen=pathAt(raw.mark,liq.asOf,(e.decisionAt-liq.asOf)/S);if(!seen)return{status:'GAP_MODEL_TO_SIGNAL',asOf:liq.asOf};const seenLow=Math.min(reference,...seen.map(b=>+b[3]));
const zone=liq.zones.filter(z=>z.high<Math.min(reference*.999,seenLow)&&z.high>=reference*.95).sort((a,b)=>b.high-a.high)[0];
const brief={asOf:liq.asOf,reference,lowerScore:liq.lowerScore,upperScore:liq.upperScore,zone:zone??null};
if(!zone)return{status:'NO_UNTOUCHED_LOWER_ZONE_5PCT',...brief};
const wait=pathAt(raw.mark,e.decisionAt,(e.entryAt-e.decisionAt)/S);if(!wait)return{status:'GAP_SIGNAL_TO_ENTRY',...brief};const waitLow=Math.min(...wait.map(b=>+b[3]));if(waitLow<=zone.high)return{status:'TOUCHED_BEFORE_ENTRY',...brief};
const path=pathAt(raw.mark,e.entryAt,96);if(!path)return{status:'MISSING_FUTURE_MARK',...brief};const entry=+path[0][1];if(!(entry>zone.high))return{status:'TOUCHED_BEFORE_ENTRY',...brief};let touchAt=null,sweepAt=null;
for(const b of path){if(touchAt===null&&+b[3]<=zone.high)touchAt=+b[6];if(sweepAt===null&&+b[3]<=zone.low)sweepAt=+b[6];}
return{status:'OK',...brief,entry,distancePct:(1-zone.low/entry)*100,touch:touchAt!==null,swept:sweepAt!==null,touchAt,sweepAt,horizons:Object.fromEntries([1,4,8].map(h=>[h+'h',{touch:touchAt!==null&&touchAt<e.entryAt+h*H,swept:sweepAt!==null&&sweepAt<e.entryAt+h*H}]))};}
export function metrics(xs){const rows=xs.filter(r=>r.trade?.status==='OK'),n=rows.length,mean=vs=>vs.length?vs.reduce((a,b)=>a+b,0)/vs.length:null;const zs=rows.filter(r=>r.model.status==='OK'),avg=mean(rows.map(r=>r.trade.netRoe)),g=rows.filter(r=>r.trade.netRoe>0).reduce((s,r)=>s+r.trade.netRoe,0),loss=-rows.filter(r=>r.trade.netRoe<0).reduce((s,r)=>s+r.trade.netRoe,0);
return{n,coins:new Set(rows.map(r=>r.symbol)).size,winPct:n?100*rows.filter(r=>r.trade.netRoe>0).length/n:null,meanRoe:avg,stressMeanRoe:mean(rows.map(r=>r.trade.stressRoe)),profitFactor:loss?g/loss:null,tp:rows.filter(r=>r.trade.kind.startsWith('TP')).length,sl:rows.filter(r=>r.trade.kind.startsWith('SL')).length,down1Pct:n?100*rows.filter(r=>r.excursion.down1).length/n:null,down2Pct:n?100*rows.filter(r=>r.excursion.down2).length/n:null,down3Pct:n?100*rows.filter(r=>r.excursion.down3).length/n:null,direction:Object.fromEntries([1,4,8].map(h=>[h+'h',{correctPct:n?100*rows.filter(r=>r.trade.directionalReturns[h+'h']>0).length/n:null,meanShortReturnPct:mean(rows.map(r=>r.trade.directionalReturns[h+'h']))}])),model:{n:zs.length,touchPct:zs.length?100*zs.filter(r=>r.model.touch).length/zs.length:null,sweepPct:zs.length?100*zs.filter(r=>r.model.swept).length/zs.length:null,meanDistancePct:mean(zs.map(r=>r.model.distancePct)),statuses:Object.fromEntries([...new Set(rows.map(r=>r.model.status))].map(s=>[s,rows.filter(r=>r.model.status===s).length]))},lag10:{n:rows.filter(r=>r.model10.status==='OK').length,sweepPct:(()=>{const z=rows.filter(r=>r.model10.status==='OK');return z.length?100*z.filter(r=>r.model10.swept).length/z.length:null;})()}};}

